"""Parsers for catalog.txt, movements.txt and orders.txt."""

import datetime
import re
from dataclasses import dataclass, field
from decimal import Decimal
from typing import Dict, Iterator, List, Optional, Sequence, Tuple

WS = " \t"  # the only whitespace the file formats know about

SKU_RE = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}", re.ASCII)
PRICE_RE = re.compile(r"([0-9]+)(?:\.([0-9]{1,2}))?", re.ASCII)
UINT_RE = re.compile(r"[0-9]+", re.ASCII)
SIGNED_RE = re.compile(r"[+-]?[0-9]+", re.ASCII)
DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})", re.ASCII)
ORDER_ID_RE = re.compile(r"[Ss][Oo]-[0-9]+", re.ASCII)
MOVEMENT_RE = re.compile(r"([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(?:[ \t]+(.*))?")
TAX_RATES = {"standard": 20, "reduced": 5, "zero": 0}


class ParseError(ValueError):
    """A mistake in one line of a data file."""

    def __init__(self, message: str, line: Optional[int] = None) -> None:
        self.message = message
        self.line = line
        text = "line %d: %s" % (line, message) if line is not None else message
        super().__init__(text)


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str = "standard"


@dataclass(frozen=True)
class Movement:
    date: datetime.date
    sku: str
    quantity: int
    note: str = ""
    line: int = field(default=0, compare=False, repr=False)


@dataclass(frozen=True)
class Order:
    id: str
    date: datetime.date
    customer: str
    lines: List[Tuple[str, int]]
    line: int = field(default=0, compare=False, repr=False)


def parse_date(text: str) -> Optional[datetime.date]:
    """The date for ``YYYY-MM-DD`` text, or None when it is not a real date."""
    m = DATE_RE.fullmatch(text)
    if not m:
        return None
    try:
        return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        return None


def normalise_sku(text: str) -> Optional[str]:
    """Upper-case SKU for text that follows the SKU grammar, else None."""
    if SKU_RE.fullmatch(text):
        return text.upper()
    return None


def normalise_order_id(text: str) -> Optional[str]:
    if ORDER_ID_RE.fullmatch(text):
        return text.upper()
    return None


def _content_lines(text: str) -> Iterator[Tuple[int, str]]:
    """Yield (line number, trimmed text) for every line that is not blank or a comment."""
    if text.startswith("﻿"):
        text = text[1:]
    for number, raw in enumerate(text.split("\n"), 1):
        if raw.endswith("\r"):
            raw = raw[:-1]
        line = raw.strip(WS)
        if not line or line.startswith("#"):
            continue
        yield number, line


def parse_catalog(text: str) -> Dict[str, Product]:
    catalog = {}  # type: Dict[str, Product]
    for number, line in _content_lines(text):
        fields = [f.strip(WS) for f in line.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError("expected 4 or 5 fields separated by '|', found %d" % len(fields), number)
        sku_text, name, price_text, reorder_text = fields[:4]
        sku = normalise_sku(sku_text)
        if sku is None:
            raise ParseError("bad SKU %r" % sku_text, number)
        if sku in catalog:
            raise ParseError("duplicate SKU %s" % sku, number)
        if not name:
            raise ParseError("empty name", number)
        m = PRICE_RE.fullmatch(price_text)
        if not m:
            raise ParseError("bad price %r" % price_text, number)
        price = Decimal("%s.%s" % (m.group(1), (m.group(2) or "").ljust(2, "0")))
        if price < Decimal("0.01"):
            raise ParseError("price must be at least 0.01", number)
        if not UINT_RE.fullmatch(reorder_text):
            raise ParseError("bad reorder level %r" % reorder_text, number)
        tax = "standard"
        if len(fields) == 5:
            tax_text = fields[4]
            tax = tax_text.lower() if tax_text.isascii() else ""
            if tax not in TAX_RATES:
                raise ParseError("bad tax %r (expected standard, reduced or zero)" % tax_text, number)
        catalog[sku] = Product(sku, name, price, int(reorder_text), tax)
    return catalog


def _to_int(text: str, number: int, what: str) -> int:
    try:
        return int(text)
    except ValueError:
        raise ParseError("%s is too large" % what, number) from None


def parse_movements(text: str, catalog: Dict[str, Product]) -> List[Movement]:
    movements = []  # type: List[Movement]
    for number, line in _content_lines(text):
        m = MOVEMENT_RE.fullmatch(line)
        if not m:
            raise ParseError("expected DATE SKU QUANTITY [NOTE]", number)
        date_text, sku_text, qty_text, note = m.group(1), m.group(2), m.group(3), m.group(4) or ""
        date = parse_date(date_text)
        if date is None:
            raise ParseError("bad date %r" % date_text, number)
        sku = normalise_sku(sku_text)
        if sku is None:
            raise ParseError("bad SKU %r" % sku_text, number)
        if sku not in catalog:
            raise ParseError("SKU %s is not in the catalogue" % sku, number)
        if not SIGNED_RE.fullmatch(qty_text):
            raise ParseError("bad quantity %r" % qty_text, number)
        quantity = _to_int(qty_text, number, "quantity")
        if quantity == 0:
            raise ParseError("quantity must not be zero", number)
        movements.append(Movement(date, sku, quantity, note, number))
    validate_movements(movements)
    return movements


def validate_movements(movements: Sequence[Movement]) -> None:
    """Raise ParseError for the movement that takes a product below zero (date order, stable)."""
    stock = {}  # type: Dict[str, int]
    for move in sorted(movements, key=lambda mv: mv.date):
        level = stock.get(move.sku, 0) + move.quantity
        if level < 0:
            raise ParseError(
                "stock of %s would go below zero (%d on %s)" % (move.sku, level, move.date.isoformat()),
                move.line,
            )
        stock[move.sku] = level


def parse_orders(text: str, catalog: Dict[str, Product]) -> List[Order]:
    orders = []  # type: List[Order]
    seen = set()
    for number, line in _content_lines(text):
        fields = re.split(r"[ \t]+", line)
        if len(fields) != 4:
            raise ParseError("expected ORDER DATE CUSTOMER LINES", number)
        id_text, date_text, customer, lines_text = fields
        order_id = normalise_order_id(id_text)
        if order_id is None:
            raise ParseError("bad order number %r" % id_text, number)
        if order_id in seen:
            raise ParseError("duplicate order %s" % order_id, number)
        date = parse_date(date_text)
        if date is None:
            raise ParseError("bad date %r" % date_text, number)
        lines = []  # type: List[Tuple[str, int]]
        used = set()
        for part in lines_text.split(","):
            pair = part.split("*")
            if len(pair) != 2:
                raise ParseError("bad order line %r (expected SKU*QUANTITY)" % part, number)
            sku = normalise_sku(pair[0])
            if sku is None:
                raise ParseError("bad SKU %r" % pair[0], number)
            if sku not in catalog:
                raise ParseError("SKU %s is not in the catalogue" % sku, number)
            if sku in used:
                raise ParseError("SKU %s appears twice in the order" % sku, number)
            if not UINT_RE.fullmatch(pair[1]):
                raise ParseError("bad quantity %r" % pair[1], number)
            quantity = _to_int(pair[1], number, "quantity")
            if quantity < 1:
                raise ParseError("quantity must be at least 1", number)
            used.add(sku)
            lines.append((sku, quantity))
        seen.add(order_id)
        orders.append(Order(order_id, date, customer, lines, number))
    return orders
